export const ESCALATION_LABEL: Record<EscalationLevel, string> = {
  OFFICER: 'Site officer',
  PATROL: 'Patrolling officer',
  OM: 'Operations Manager',
  ROM: 'Regional Operations Manager',
  HEAD: 'Head of operations',
  COO: 'Chief Operating Officer',
  CEO: 'Chief Executive Officer',
  DONE: 'Fully resolved',
};
/** The head of operations depends on the site's sector: OGM for government sites, Operations Director for private. */
export function levelLabel(level: EscalationLevel, sector?: Site['sector']): string {
  if (level !== 'HEAD') return ESCALATION_LABEL[level];
  return sector === 'government' ? 'Operations General Manager' : 'Operations Director';
}
/** Levels every site case passes, in order; the ROM confirms it fully resolved. No site officer where none is stationed. */
const LADDER: Exclude<EscalationLevel, 'DONE' | 'HEAD' | 'COO' | 'CEO'>[] = ['OFFICER', 'PATROL', 'OM', 'ROM'];
/**
 * Above the Regional OM only by decision (Fauzan, 25 Oct 2026): a big matter the ROM thinks needs it, or one that
 * could not be resolved at the ROM or head-of-operations level. Never by time alone.
 */
const ABOVE_ROM: Exclude<EscalationLevel, 'DONE'>[] = ['HEAD', 'COO', 'CEO'];
const LEVEL_RANK: Record<EscalationLevel, number> = { OFFICER: 1, PATROL: 2, OM: 3, ROM: 4, HEAD: 5, COO: 6, CEO: 7, DONE: 8 };

function caseLevel(c: Case): EscalationLevel {
  return c.level ?? (c.status === 'resolved' || c.status === 'closed' ? 'DONE' : 'PATROL');
}

/** How many full time limits the case has waited at its current level: each one lets the next level up step in. */
function overduePeriods(c: Case, now: IsoDateTime): number {
  const limit = RULES.caseEscalation.value[c.severity] * 60_000;
  return Math.max(0, Math.floor((toMs(now) - toMs(c.levelSince ?? c.openedAt)) / limit));
}

function ladderState(c: Case, now: IsoDateTime): NonNullable<CaseView['ladder']> {
  const level = caseLevel(c);
  if (level === 'DONE' || c.status === 'closed') return { level: 'DONE', dueAt: null, overdue: false, nextLevel: null };
  const since = c.levelSince ?? c.openedAt;
  const dueAt = addMinutes(since, RULES.caseEscalation.value[c.severity]);
  const i = LADDER.indexOf(level as (typeof LADDER)[number]);
  return { level, dueAt, overdue: toMs(now) > toMs(dueAt), nextLevel: i >= 0 ? (LADDER[i + 1] ?? 'DONE') : 'DONE' };
}

