/** The seats a day needs under the settings: each shift window times the posts. */
export function cmsSeats(set: CmsSettings, date: IsoDate): CmsShift[] {
  const hours = set.shiftPattern === '2x12' ? 12 : 8;
  const count = 24 / hours;
  const seats: CmsShift[] = [];
  const first = toMs(myt(date, set.firstShiftStart));
  for (let i = 0; i < count; i++) {
    const startMs = first + i * hours * 3_600_000;
    const start = fromMs(startMs);
    const end = fromMs(startMs + hours * 3_600_000);
    const hhmm = start.slice(11, 16).replace(':', '');
    const add = (post: CmsPost, n: number) => {
      for (let k = 1; k <= n; k++)
        seats.push({
          id: `cms-${date}-${hhmm}-${hours}h-${post === 'HEAD_CONTROL' ? 'hc' : 'mo'}-${k}`,
          date,
          start,
          end,
          post,
          seat: k,
          staffName: null,
          clockIn: null,
          handoverAt: null,
          handoverNote: null,
        });
    };
    add('HEAD_CONTROL', set.headControlPerShift);
    add('MONITOR_OFFICER', set.monitorOfficersPerShift);
  }
  return seats;
}

function cmsOrder(a: CmsShift, b: CmsShift): number {
  return a.start.localeCompare(b.start) || a.post.localeCompare(b.post) || a.seat - b.seat;
}

export function cmsShiftState(s: CmsShift, nowMs: number, graceMin: number): 'uncovered' | 'done' | 'later' | 'on_duty' | 'no_show' | 'awaiting' {
  if (!s.staffName) return 'uncovered';
  if (toMs(s.end) <= nowMs) return 'done';
  if (toMs(s.start) > nowMs) return 'later';
  if (s.clockIn) return 'on_duty';
  return nowMs - toMs(s.start) > graceMin * 60_000 ? 'no_show' : 'awaiting';
}

function canRunCms(user: User): boolean {
  return user.role === 'director' || isArmsOnly(user);
}

function isArmsOnly(user: User): boolean {
  return user.role === 'pwvsb_officer' && user.department === 'arms_control';
}

const CLAIM_VEHICLES: ClaimVehicle[] = ['CAR', 'MOTORCYCLE', 'COMPANY_CAR'];

const SEVERITY_ORDER: Record<Severity, number> = { P1: 0, P2: 1, P3: 2, P4: 3 };

function caseOrder(a: CaseView, b: CaseView): number {
  const done = (c: CaseView) => (c.status === 'resolved' || c.status === 'closed' ? 1 : 0);
  return done(a) - done(b) || SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity] || b.openedAt.localeCompare(a.openedAt);
}

/**
 * Whose records a PWVSB department works with (Fauzan, 26 Oct 2026): FWM only foreign workers, central HR only local
 * workers and staff. Group leadership and company staff are not narrowed here.
 */
function inLine(user: User, person: Pick<Person, 'nationality'>): boolean {
  if (user.role !== 'pwvsb_officer' || isGroupLeader(user)) return true;
  if (user.department === 'fwm') return person.nationality !== 'MY';
  if (user.department === 'hr') return person.nationality === 'MY';
  return true;
}

const JA_SEVERITY: Severity[] = ['P1', 'P2', 'P3', 'P4'];
const JA_PAPERS: JaPaper[] = ['PLKS', 'PASSPORT', 'FOMEMA', 'FWIG', 'SPIKPA', 'KDN_LETTER'];
const JA_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Check one JA record's fields and keep only what Prima uses. */
function jaBody(dataset: JaDataset, it: Record<string, unknown>): JaPayroll | JaWorker | JaIncident {
  const text = (v: unknown, name: string, max = 500) => {
    if (typeof v !== 'string' || !v.trim() || v.length > max) throw new BadRequest(`${name} is missing or too long.`);
    return v.trim();
  };
  const opt = (v: unknown, max = 200) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : null);
  const money = (v: unknown, name: string) => {
    if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) throw new BadRequest(`${name} must be an amount in RM.`);
    return Math.round(v * 100) / 100;
  };
  const date = (v: unknown, name: string) => {
    if (v == null) return null;
    if (typeof v !== 'string' || !JA_DATE.test(v)) throw new BadRequest(`${name} must be a date like 2026-10-26.`);
    return v;
  };
  const time = (v: unknown, name: string) => {
    if (typeof v !== 'string' || Number.isNaN(Date.parse(v))) throw new BadRequest(`${name} must be a date and time.`);
    return fromMs(Date.parse(v));
  };
  if (dataset === 'payroll') {
    const period = text(it.period, 'period', 7);
    if (!/^\d{4}-\d{2}$/.test(period)) throw new BadRequest('period must be a month like 2026-10.');
    const status = it.status;
    if (status !== 'draft' && status !== 'approved' && status !== 'paid') throw new BadRequest('status must be draft, approved or paid.');
    const headcount = it.headcount;
    if (typeof headcount !== 'number' || !Number.isInteger(headcount) || headcount < 0) throw new BadRequest('headcount must be a whole number.');
    return {
      period,
      headcount,
      gross: money(it.gross, 'gross'),
      net: money(it.net, 'net'),
      employerEpf: money(it.employerEpf, 'employerEpf'),
      employerSocso: money(it.employerSocso, 'employerSocso'),
      employerEis: money(it.employerEis, 'employerEis'),
      ...(it.employeeSocso == null ? {} : { employeeSocso: money(it.employeeSocso, 'employeeSocso') }),
      ...(it.employeeLindung == null ? {} : { employeeLindung: money(it.employeeLindung, 'employeeLindung') }),
      ...(it.employeeEis == null ? {} : { employeeEis: money(it.employeeEis, 'employeeEis') }),
      pcb: money(it.pcb, 'pcb'),
      status,
      approvedBy: opt(it.approvedBy),
      approvedAt: it.approvedAt == null ? null : time(it.approvedAt, 'approvedAt'),
      paidOn: date(it.paidOn, 'paidOn'),
    };
  }
  if (dataset === 'worker') {
    const statuses: JaWorker['status'][] = ['active', 'home_leave', 'exit_pending', 'exited', 'absconded', 'other'];
    const status = statuses.includes(it.status as JaWorker['status']) ? (it.status as JaWorker['status']) : 'other';
    if (!Array.isArray(it.papers)) throw new BadRequest('papers must be a list.');
    const papers = it.papers.slice(0, 20).map((x) => {
      const p = (x ?? {}) as Record<string, unknown>;
      if (!JA_PAPERS.includes(p.paper as JaPaper)) throw new BadRequest(`Unknown paper ${String(p.paper)}.`);
      return { paper: p.paper as JaPaper, expiresOn: date(p.expiresOn, 'expiresOn'), renewalSubmittedOn: date(p.renewalSubmittedOn, 'renewalSubmittedOn') };
    });
    return {
      staffNo: text(it.staffNo, 'staffNo', 40),
      name: text(it.name, 'name', 200),
      nationality: text(it.nationality, 'nationality', 60),
      status,
      serviceYear: typeof it.serviceYear === 'number' ? it.serviceYear : null,
      siteCode: opt(it.siteCode, 40),
      hostel: opt(it.hostel, 120),
      papers,
    };
  }
  const severity = it.severity as Severity;
  if (!JA_SEVERITY.includes(severity)) throw new BadRequest('severity must be P1 to P4.');
  if (it.status !== 'open' && it.status !== 'closed') throw new BadRequest('status must be open or closed.');
  return {
    occurredAt: time(it.occurredAt, 'occurredAt'),
    siteCode: opt(it.siteCode, 40),
    category: text(it.category, 'category', 80),
    severity,
    status: it.status,
    summary: text(it.summary, 'summary', 2000),
    reportedBy: opt(it.reportedBy),
    closedAt: it.closedAt == null ? null : time(it.closedAt, 'closedAt'),
  };
}

/** Whether the JA Group app is the system of record for an area (rule SYS-JA-OWNS); Prima's own version is then switched off. */
export function jaOwns(area: JaArea): boolean {
  return RULES.jaGroupApp.value.owns.includes(area);
}

/** Agenda lines, without numbering or bullets the organiser typed. */
export function agendaItems(agenda: string): string[] {
  return (agenda ?? '')
    .split(/\r?\n/)
    .map((x) => x.replace(/^\s*(?:\d+[.)]|[-*•])\s*/, '').trim())
    .filter(Boolean)
    .slice(0, 40);
}

/** The pre-briefing checklist for a kind of meeting (rule MTG-PREP). */
export function defaultMeetingPrep(kind: Meeting['kind']): NonNullable<Meeting['prep']> {
  const r = RULES.meetingPrep.value;
  return [...r.common, ...(r.byKind[kind] ?? [])].map((label) => ({ label, done: false, by: null, at: null }));
}

/** Old and new value of every field changed on a record form, for the audit log (Fauzan, 27 Oct 2026). */
export function recordChanges(spec: (typeof RECORD_KINDS)[RecordKind], before: RecordValues, after: RecordValues): string {
  const show = (v: unknown) => (v === null || v === undefined || v === '' ? 'empty' : v === true ? 'yes' : v === false ? 'no' : String(v));
  return spec.fields
    .filter((f) => f.key in after && show(before[f.key]) !== show(after[f.key]))
    .map((f) => {
      const val = (x: unknown) => (f.restricted && show(x) !== 'empty' ? `****${String(x).slice(-4)}` : show(x));
      return `${f.label}: ${val(before[f.key])} → ${val(after[f.key])}`;
    })
    .join('; ');
}

/** A firearm as every screen but the Arms Control form sees it: the full serial number left out. */
function withoutSerial(f: Firearm): Firearm {
  const { serial: _serial, ...rest } = f;
  return rest;
}

/**
 * When an unpaid unit's status was last updated and when the next update is due (rule AM-WATCH, every 10 days until
 * paid). A follow-up (other than a letter still waiting for approval) or a payment counts as an update. The clock starts
 * on the 1st of the oldest unpaid month. Null when nothing is unpaid.
 */
function rentUpdate(t: AmTenancy | null, today: IsoDate, everyDays: number) {
  if (!t) return null;
  const unpaid = t.invoices.filter((i) => i.paid < i.amount && i.period <= today.slice(0, 7));
  if (!unpaid.length) return null;
  const since = `${unpaid.map((i) => i.period).sort()[0]}-01`;
  const marks = [
    t.lastContactOn,
    ...(t.followUps ?? []).filter((f) => (f.action !== 'LETTER' && f.action !== 'NOTICE') || f.approval?.approve).map((f) => f.on),
    ...(t.payments ?? []).filter((p) => !p.reversed).map((p) => p.on),
  ].filter((d): d is IsoDate => !!d && d >= since);
  const last = marks.sort().at(-1) ?? null;
  const nextOn = addDays(last ?? since, everyDays);
  return { lastOn: last, nextOn, due: nextOn <= today, daysLate: Math.max(0, daysBetween(nextOn, today)) };
}

function pickKeys(r: Record<string, unknown>, keys: string[]): RecordValues {
  const out: RecordValues = {};
  for (const k of keys) {
    const v = r[k];
    out[k] = v === undefined ? null : (v as RecordValues[string]);
  }
  return out;
}

/** Offboarding in a store with no database function (the browser test version and tests): the same two writes. */
async function closeAccessInStore(tx: Store, userId: Id, from: IsoDate, closed: NonNullable<User['accessClosed']>): Promise<number> {
  await tx.update('users', userId, { accessClosedFrom: from, accessClosed: closed });
  const lastDay = addDays(from, -1);
  let n = 0;
  for (const g of await tx.list('grants', { userId }))
    if (g.validTo > lastDay) {
      await tx.update('grants', g.id, { validTo: lastDay < g.validFrom ? g.validFrom : lastDay });
      n += 1;
    }
  return n;
}
